// Octanest service worker — assets-only app-shell cache (D-30).
//
// Hand-authored fallback for vite-plugin-pwa (see 03-05-SUMMARY.md): this
// repo's Vite 8 / @octanejs/tanstack-start multi-environment build never
// invokes vite-plugin-pwa's workbox-build closeBundle hook, so no sw.js is
// generated by the plugin. This file reproduces the same D-28/D-29/D-30
// guarantees by hand: precache the static shell only, never touch /api/*
// or /health (T-03-16, HIGH), and drop stale caches on activate so a new
// deploy replaces the shell instead of pinning clients to an old bundle
// (T-03-18).
const CACHE_NAME = "octanest-shell-v2";

const PRECACHE_URLS = [
  "/favicon.ico",
  "/favicon-16.png",
  "/favicon-32.png",
  "/apple-touch-icon.png",
  "/manifest.webmanifest",
  "/icons/icon-192.png",
  "/icons/icon-512.png",
  "/icons/icon-512-maskable.png",
  "/fonts/sora-latin.woff2",
  "/fonts/source-sans-3-latin.woff2",
];

self.addEventListener("install", (event) => {
  event.waitUntil(
    caches
      .open(CACHE_NAME)
      .then((cache) => cache.addAll(PRECACHE_URLS))
      .then(() => self.skipWaiting()),
  );
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((keys) =>
        Promise.all(keys.filter((key) => key !== CACHE_NAME).map((key) => caches.delete(key))),
      )
      .then(() => self.clients.claim()),
  );
});

self.addEventListener("fetch", (event) => {
  const url = new URL(event.request.url);

  // T-03-16 (HIGH): API, RPC, and health traffic must never be cached in
  // either direction — pass every such request straight to the network,
  // untouched, with no caches.match / caches.put on either side.
  if (url.pathname.startsWith("/api/") || url.pathname === "/health") {
    event.respondWith(fetch(event.request));
    return;
  }

  if (event.request.method !== "GET") return;

  if (PRECACHE_URLS.includes(url.pathname)) {
    event.respondWith(caches.match(event.request).then((cached) => cached || fetch(event.request)));
  }
});
